public void join(final byte[] password) throws OperationFailedException {
  final IrcConnection connection=this.parentProvider.getIrcStack().getConnection();
  if (connection == null) {
    throw new OperationFailedException("We are currently not connected to the server.",OperationFailedException.NETWORK_FAILURE);
  }
  if (connection.getChannelManager().isJoined(this)) {
    throw new OperationFailedException("Channel is already joined.",OperationFailedException.SUBSCRIPTION_ALREADY_EXISTS);
  }
  try {
    final String chatRoomId = connection.getChannelManager().getChatRoomId(this);
    if (chatRoomId == null || chatRoomId.isEmpty()) {
      throw new OperationFailedException("Invalid chat room ID", OperationFailedException.ILLEGAL_ARGUMENT);
    }
    connection.getChannelManager().join(this, password != null ? new String(password) : "");
  } catch (final IllegalArgumentException e) {
    throw new OperationFailedException(e.getMessage(), OperationFailedException.CHAT_ROOM_NOT_JOINED, e);
  } catch (final IndexOutOfBoundsException e) {
    throw new OperationFailedException("Invalid chat room ID format", OperationFailedException.ILLEGAL_ARGUMENT, e);
  } catch (final NullPointerException e) {
    throw new OperationFailedException("Null parameters encountered", OperationFailedException.ILLEGAL_ARGUMENT, e);
  }
}
